/**
 * Lock object (ENQU) content XML builder, shared by Create/Update handlers.
 *
 * <enqu:content> holds allowRFC, the primary table + lock mode, and secondary
 * tables. lockParameters and lockModules (ENQUEUE_/DEQUEUE_ function modules)
 * are GENERATED by SAP on activation, so they are intentionally not sent.
 */
import { escXml } from './adtObjectOps';

export { escXml };

export interface LockContentInput {
  allowRfc: boolean;
  primaryTable: string;
  lockMode: string; // E | S | X | O
}

export function buildLockContent(input: LockContentInput): string {
  return (
    `<enqu:content>` +
    `<enqu:allowRFC>${input.allowRfc ? 'true' : 'false'}</enqu:allowRFC>` +
    `<enqu:primaryTable>` +
    `<enqu:tableName>${escXml(input.primaryTable)}</enqu:tableName>` +
    `<enqu:lockMode>${escXml(input.lockMode)}</enqu:lockMode>` +
    `</enqu:primaryTable>` +
    `<enqu:secondaryTables/>` +
    `</enqu:content>`
  );
}
